-- Упражнения книги 17 «virt — Виртуализация». Файл строит export_tasks.py — руками не правьте.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 1, 'virt-ffd-hosts', 0, 'func', 'Сколько серверов нужно', 'Напишите функцию hosts_needed(loads, capacity): loads — нагрузки виртуальных машин в условных единицах процессора, capacity — вместимость одного сервера. Раскладывайте жадно: сначала машины по убыванию нагрузки, каждую — на первый сервер, где она помещается, иначе открывайте новый. Верните число серверов. Если какая-то нагрузка больше capacity, верните -1.', 'def hosts_needed(loads, capacity):
    pass
', 'Держите список свободного места на уже открытых серверах; sorted(loads, reverse=True) даёт порядок.', '{"func": "hosts_needed", "tests": [{"args": [[], 10], "expected": 0}, {"args": [[4, 4, 4], 10], "expected": 2}, {"args": [[5, 5, 5, 5], 10], "expected": 2}, {"args": [[7, 3, 6, 4], 10], "expected": 2}, {"args": [[11], 10], "expected": -1}, {"args": [[6, 6, 6], 10], "expected": 3}, {"args": [[2, 2, 2, 2, 2, 2], 5], "expected": 3}, {"args": [[5, 4, 3, 3, 2, 2, 1], 10], "expected": 2}, {"args": [[9, 1, 8, 2, 7, 3], 10], "expected": 3}, {"args": [[3, 3, 3, 3, 3, 3, 3, 3, 3, 3], 10], "expected": 4}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 1, 'virt-peaks', 1, 'func', 'Сумма пиков и пик суммы', 'Напишите функцию consolidation(series, capacity): series — список рядов нагрузки (по часам) для каждой виртуальной машины, все ряды одной длины, capacity — вместимость сервера. Верните кортеж из двух чисел: сколько серверов нужно, если считать пик каждой машины отдельно (сумма максимумов, делённая на capacity с округлением вверх), и сколько — если считать общий пик (максимум по часам суммарной нагрузки, тоже вверх). Для пустого списка верните (0, 0).', 'def consolidation(series, capacity):
    pass
', 'Суммарную нагрузку по часам даёт zip(*series); округление вверх — -(-x // capacity).', '{"func": "consolidation", "tests": [{"args": [[[6, 1], [1, 6]], 4], "expected": {"__tuple__": [3, 2]}}, {"args": [[[2, 2, 2]], 2], "expected": {"__tuple__": [1, 1]}}, {"args": [[[5, 0, 0], [0, 5, 0], [0, 0, 5]], 5], "expected": {"__tuple__": [3, 1]}}, {"args": [[], 10], "expected": {"__tuple__": [0, 0]}}, {"args": [[[3, 3], [3, 3]], 6], "expected": {"__tuple__": [1, 1]}}, {"args": [[[10, 0, 4], [0, 9, 4], [1, 1, 4]], 8], "expected": {"__tuple__": [3, 2]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 1, 'virt-popek', 2, 'func', 'Теорема Попека и Голдберга', 'Напишите функцию check_isa(isa): isa — словарь «имя команды → [привилегированная, чувствительная]» (два логических значения). Верните кортеж (можно ли построить монитор по теореме Попека и Голдберга, отсортированный список «дыр»), где дыра — чувствительная, но не привилегированная команда. Привилегированная нечувствительная команда не мешает.', 'def check_isa(isa):
    pass
', 'Монитор строится, когда дыр нет.', '{"func": "check_isa", "tests": [{"args": [{"ADD": [false, false], "CLI": [true, true], "LGDT": [true, true]}], "expected": {"__tuple__": [true, []]}}, {"args": [{"ADD": [false, false], "CLI": [true, true], "POPF": [false, true]}], "expected": {"__tuple__": [false, ["POPF"]]}}, {"args": [{"HLT": [true, true], "POPF": [false, true], "SGDT": [false, true]}], "expected": {"__tuple__": [false, ["POPF", "SGDT"]]}}, {"args": [{}], "expected": {"__tuple__": [true, []]}}, {"args": [{"IN": [true, false], "MOV": [false, false]}], "expected": {"__tuple__": [true, []]}}, {"args": [{"ADD": [false, false], "CLI": [true, true], "LAR": [false, true], "SMSW": [false, true]}], "expected": {"__tuple__": [false, ["LAR", "SMSW"]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 1, 'virt-conflicts', 3, 'func', 'Чужая память', 'Монитор обязан не давать гостю чужую память. Напишите функцию find_conflicts(regions): regions — список областей [имя_ВМ, начало, размер]. Область занимает адреса от начала до начала + размер (не включая конец). Верните отсортированный список кортежей (a, b), где a < b — имена двух разных машин, у которых есть пересекающиеся области; каждая пара один раз. Области одной машины между собой не конфликтуют, область нулевого размера не пересекается ни с чем.', 'def find_conflicts(regions):
    pass
', 'Две области пересекаются, когда начало каждой меньше конца другой.', '{"func": "find_conflicts", "tests": [{"args": [[["a", 0, 100], ["b", 100, 100]]], "expected": []}, {"args": [[["a", 0, 100], ["b", 99, 10]]], "expected": [{"__tuple__": ["a", "b"]}]}, {"args": [[["a", 0, 50], ["a", 25, 50]]], "expected": []}, {"args": [[["a", 0, 10], ["b", 5, 10], ["c", 8, 10]]], "expected": [{"__tuple__": ["a", "b"]}, {"__tuple__": ["a", "c"]}, {"__tuple__": ["b", "c"]}]}, {"args": [[["b", 0, 10], ["a", 5, 10]]], "expected": [{"__tuple__": ["a", "b"]}]}, {"args": [[["a", 0, 0], ["b", 0, 10]]], "expected": []}, {"args": [[["a", 0, 10], ["b", 20, 5], ["c", 22, 5], ["a", 100, 5]]], "expected": [{"__tuple__": ["b", "c"]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 1, 'virt-direct-percent', 4, 'func', 'Какая доля команд идёт напрямую', 'Напишите функцию direct_percent(trace, privileged): trace — список имён команд, выполненных гостем, privileged — список имён привилегированных команд (они идут через монитор). Верните целый процент команд, выполненных напрямую, округлённый вниз. Для пустого trace верните 100.', 'def direct_percent(trace, privileged):
    pass
', 'Считайте команды, которых нет в privileged, и умножайте на 100 до деления.', '{"func": "direct_percent", "tests": [{"args": [[], ["CLI"]], "expected": 100}, {"args": [["ADD", "ADD", "CLI", "ADD"], ["CLI"]], "expected": 75}, {"args": [["CLI", "HLT"], ["CLI", "HLT"]], "expected": 0}, {"args": [["ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "ADD", "